inputs.expression:
(
    $oo := inputs.TEDS_Object.observables ;

    $raw_type := $type($oo) ;

    $real_type := ($raw_type = "array" and $count($oo) = 0) ? "empty_array"
               :  ($raw_type = "array" and $count($oo) = $count($oo[observable_type and observable_value])) ? "valid_array"
               :  ($raw_type = "array" and $not($count($oo) = $count($oo[observable_type and observable_value]))) ? "invalid_array"
               :  ($raw_type = "string" and $length($oo) = 0) ? "empty_string"
               :  ($raw_type = "string" and $length($oo) > 0) ? "valid_string" 
               : "invalid_object" ;



    $o_count :=  ($real_type = "valid_string") ? -1 /* Unknown but must run through Parse IOCs */
               : ($real_type = "empty_string") ? 0 /* Do not run through Parse IOCs */
               : ($real_type = "valid_array") ? $count($oo) /* Get real count of valid array objects */
               : ($real_type = "invalid_array") ? -1 /* Unknown */
               : ($real_type = "empty_array") ? 0 /* No valid objects in array */
               : -1 ; /* Unknown for Invalid object */

    $ret := {
        "observable_object_type": $real_type,
        "observables_count": $o_count
    } ;

)
